    #[test]
    fn extern_invocation_permission_matrix() {
        const PERMISSION: &str = "calling extern function 'foreign' requires an unsafe { } block";
        const FN_VALUE: &str = "extern function 'foreign' cannot be used as a function value; call it directly inside unsafe";

        let (program, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn bad() -> i64 { return foreign() }\nfn main() -> i32 = 0\n",
        );
        let errors = diagnostics
            .iter()
            .filter(|d| d.severity == align_diag::Severity::Error)
            .collect::<Vec<_>>();
        assert_eq!(errors.iter().map(|d| d.message.as_str()).collect::<Vec<_>>(), [PERMISSION]);
        let bad = program.fns.iter().find(|f| f.name == "bad").expect("bad function");
        assert!(matches!(
            bad.body.stmts.first(),
            Some(Stmt::Return(Some(Expr { kind: ExprKind::Bool(false), ty: Ty::Error, .. })))
        ), "a forbidden direct call must not enter HIR as Call: {:?}", bad.body.stmts);

        let (_, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn good() -> i64 { unsafe { return foreign(1) } }\nfn main() -> i32 = 0\n",
        );
        assert!(!diagnostics.has_errors(), "a direct extern call in unsafe must check: {:?}", diagnostics.iter().collect::<Vec<_>>());

        let (_, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn bad() -> i32 { f := foreign\nreturn 0 }\nfn main() -> i32 = 0\n",
        );
        let messages = diagnostics
            .iter()
            .filter(|d| d.severity == align_diag::Severity::Error)
            .map(|d| d.message.as_str())
            .collect::<Vec<_>>();
        assert_eq!(messages, [FN_VALUE], "extern declarations cannot form FnValue: {messages:?}");

        let callback_sources = [
            ("fn bad() -> i32 { [1, 2].map(foreign).sum()\nreturn 0 }", "foreign"),
            ("fn bad() -> i32 { [1, 2].where(predicate).sum()\nreturn 0 }", "predicate"),
            ("fn bad() -> i32 { [1, 2].reduce(0, fold)\nreturn 0 }", "fold"),
            ("fn bad() -> i32 { [1, 2].partition(predicate)\nreturn 0 }", "predicate"),
            ("fn bad() -> i32 { [1, 2].any(predicate)\nreturn 0 }", "predicate"),
            ("fn bad() -> i32 { [1, 2].all(predicate)\nreturn 0 }", "predicate"),
            ("fn bad() -> i32 { [1, 2].par_map(foreign).sum()\nreturn 0 }", "foreign"),
            ("fn bad() -> i32 { [1, 2].scan(0, fold)\nreturn 0 }", "fold"),
            ("fn bad() -> i32 { [1, 2].sort_by_key(foreign)\nreturn 0 }", "foreign"),
        ];
        for (body, name) in callback_sources {
            let source = format!(
                "extern \"C\" fn foreign(x: i64) -> i64\nextern \"C\" fn predicate(x: i64) -> i32\nextern \"C\" fn fold(a: i64, b: i64) -> i64\n{body}\nfn main() -> i32 = 0\n"
            );
            let (_, diagnostics) = check(&source);
            let messages = diagnostics
                .iter()
                .filter(|d| d.severity == align_diag::Severity::Error)
                .map(|d| d.message.clone())
                .collect::<Vec<_>>();
            assert_eq!(messages, vec![format!("calling extern function '{name}' requires an unsafe {{ }} block")], "callback must be gated before shape checking: {body}: {messages:?}");
        }

        let (program, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn bad() -> i32 { [1, 2].map(foreign).sum()\nreturn 0 }\nfn main() -> i32 = 0\n",
        );
        assert_eq!(
            diagnostics
                .iter()
                .filter(|d| d.severity == align_diag::Severity::Error)
                .map(|d| d.message.as_str())
                .collect::<Vec<_>>(),
            [PERMISSION],
            "a rejected named callback must not cascade into terminal diagnostics"
        );
        let bad = program.fns.iter().find(|f| f.name == "bad").expect("bad callback function");
        assert!(matches!(
            bad.body.stmts.first(),
            Some(Stmt::Expr(Expr { kind: ExprKind::Bool(false), ty: Ty::Error, .. }))
        ), "a rejected callback pipeline must not enter HIR as an Array* node: {:?}", bad.body.stmts);

        let permitted_callbacks = [
            "[1, 2].map(foreign).sum()",
            "[1, 2].where(predicate).sum()",
            "[1, 2].reduce(0, fold)",
            "[1, 2].partition(predicate)",
            "[1, 2].any(predicate)",
            "[1, 2].all(predicate)",
            "[1, 2].par_map(foreign).sum()",
            "[1, 2].scan(0, fold)",
            "[1, 2].sort_by_key(foreign)",
        ];
        for body in permitted_callbacks {
            let source = format!(
                "extern \"C\" fn foreign(x: i64) -> i64\nextern \"C\" fn predicate(x: i64) -> i32\nextern \"C\" fn fold(a: i64, b: i64) -> i64\nfn good() -> i32 {{ unsafe {{ {body} }}\nreturn 0 }}\nfn main() -> i32 = 0\n"
            );
            let (_, diagnostics) = check(&source);
            assert!(
                !diagnostics.iter().any(|d| d.message == PERMISSION),
                "owning callback expression in unsafe must pass the permission gate: {body}: {:?}",
                diagnostics.iter().map(|d| &d.message).collect::<Vec<_>>()
            );
        }

        let (_, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn bad() -> i64 { unsafe { return [1].map(fn x { if x > 0 { foreign(x) } else { x } }).sum() } }\nfn main() -> i32 = 0\n",
        );
        assert_eq!(
            diagnostics
                .iter()
                .filter(|d| d.severity == align_diag::Severity::Error)
                .map(|d| d.message.as_str())
                .collect::<Vec<_>>(),
            [PERMISSION],
            "a lifted lambda has its own lexical unsafe depth"
        );

        for body in [
            "loop { break foreign(x) }",
            "return foreign(x)",
        ] {
            let source = format!(
                "extern \"C\" fn foreign(x: i64) -> i64\nfn bad() -> i64 {{ unsafe {{ return [1].map(fn x {{ {body} }}).count() }} }}\nfn main() -> i32 = 0\n"
            );
            let (_, diagnostics) = check(&source);
            let messages = diagnostics
                .iter()
                .filter(|d| d.severity == align_diag::Severity::Error)
                .map(|d| d.message.as_str())
                .collect::<Vec<_>>();
            assert_eq!(messages, [PERMISSION], "lambda control-flow boundary must reset unsafe depth: {body}: {messages:?}");
        }

        let (_, diagnostics) = check(
            "extern \"C\" fn foreign(x: i64) -> i64\nfn good() -> i64 { return [1].map(fn x { unsafe { foreign(x) } }).sum() }\nfn main() -> i32 = 0\n",
        );
        assert!(!diagnostics.has_errors(), "an unsafe block inside the lambda permits its extern call: {:?}", diagnostics.iter().collect::<Vec<_>>());
    }

    #[test]
    fn projected_return_provenance_fails_closed() {
        let (program, diagnostics) = check(
            "\
Pair { left: str, right: str }
fn probe(value: Pair, replacement: str) -> str = value.left
fn tuple(value: Pair, replacement: str) -> (str, str) = (value.left, replacement)
fn main() -> i32 = 0
",
        );
        assert!(!diagnostics.has_errors());
        let function = program
            .fns
            .iter()
            .find(|function| function.name == "probe")
            .expect("probe function");
        let named = std::collections::HashMap::new();
        let named_modes = std::collections::HashMap::new();
        let named_borrow_mut_retention = std::collections::HashMap::new();
        let callable_targets = vec![CallableTargetSet::new(); program.fn_types.len()];
        let callable_target_ids = std::collections::HashMap::new();
        let parallel_targets = CallableTransferSet::new();
        let mut sink = Diagnostics::new();
        let mut checker = MoveCheck {
            f: function,
            diags: &mut sink,
            named_return_borrow: &named,
            named_parallel_transfer: &named,
            named_param_modes: &named_modes,
            named_borrow_mut_retention: &named_borrow_mut_retention,
            summary_dependencies: None,
            tuples: &program.tuples,
            structs: &program.structs,
            enums: &program.enums,
            tagged_types: &program.tagged_types,
            fn_types: &program.fn_types,
            callable_targets: &callable_targets,
            callable_target_ids: &callable_target_ids,
            callable_parallel_targets: &parallel_targets,
            loop_breaks: Vec::new(),
            #[cfg(test)]
            loop_borrow_breaks: Vec::new(),
            #[cfg(test)]
            loop_value_breaks: Vec::new(),
            borrows: BorrowState::default(),
            next_pipeline_snapshot: 0,
            loop_value_facts: std::collections::HashMap::new(),
            control_value_facts: std::collections::HashMap::new(),
            walked_value_facts: std::collections::HashMap::new(),
            walked_storage_facts: std::collections::HashMap::new(),
            walked_backing_facts: std::collections::HashMap::new(),
            pending_call_completions: std::collections::HashMap::new(),
            mutable_call_argument_snapshots: std::collections::HashSet::new(),
            borrow_mut_place_snapshots: std::collections::HashSet::new(),
            value_snapshot_frames: Vec::new(),
            reported_invalid_value_actions: std::collections::HashSet::new(),
            loop_iter_drops: Vec::new(),
            arena_depth: 0,
            return_roots: BorrowRoots::new(),
            parallel_transfer_roots: BorrowRoots::new(),
            borrow_mut_retention: vec![BorrowRoots::new(); function.params.len()],
            non_fallthrough: std::collections::HashSet::new(),
            borrow_fact_cache: std::cell::RefCell::new(None),
            collecting_move_children: false,
            move_children: Vec::new(),
            borrowed_projection_locals: borrowed_projection_locals(&function.body),
        };
        let mut fact = BorrowFact::default();
        fact.projected.insert(
            vec![BorrowProjection::StructField(0)],
            [BorrowRoot::Param(0)].into_iter().collect(),
        );
        fact.projected.insert(
            vec![BorrowProjection::StructField(1)],
            [BorrowRoot::Param(1)].into_iter().collect(),
        );
        let all = fact.flatten();
        let pair_ty = function.locals[function.params[0] as usize].ty;
        let tuple_ty = program
            .fns
            .iter()
            .find(|function| function.name == "tuple")
            .expect("tuple function")
            .ret;
        for (ty, path) in [
            (
                Ty::Struct(u32::MAX),
                vec![BorrowProjection::StructField(0)],
            ),
            (
                Ty::Tuple(u32::MAX),
                vec![BorrowProjection::TupleElement(0)],
            ),
            (
                Ty::Tagged(u32::MAX),
                vec![BorrowProjection::OptionSome],
            ),
            (
                pair_ty,
                vec![BorrowProjection::StructField(u32::MAX)],
            ),
            (Ty::Str, vec![BorrowProjection::StructField(0)]),
        ] {
            assert_eq!(
                checker
                    .project_fact_or_flatten(ty, fact.clone(), &path, Ty::Str)
                    .flatten(),
                all,
                "malformed projection metadata must retain every current-value root: {ty:?} {path:?}"
            );
        }
        assert_eq!(
            checker
                .project_fact_or_flatten(
                    pair_ty,
                    fact.clone(),
                    &[BorrowProjection::StructField(0)],
                    Ty::Int(IntTy {
                        bits: 64,
                        signed: true,
                    }),
                )
                .flatten(),
            all,
            "a projection/result type disagreement must retain every current-value root"
        );
        let mut malformed_fact = fact.clone();
        malformed_fact.projected.insert(
            vec![BorrowProjection::StructField(u32::MAX)],
            [BorrowRoot::Param(2)].into_iter().collect(),
        );
        assert_eq!(
            checker
                .project_fact_or_flatten(
                    pair_ty,
                    malformed_fact,
                    &[BorrowProjection::StructField(0)],
                    Ty::Str,
                )
                .flatten(),
            [BorrowRoot::Param(0), BorrowRoot::Param(2)]
                .into_iter()
                .collect(),
            "an impossible stored path must become a whole-value root before later projection"
        );

        let pair_local = function.params[0];
        let replacement_local = function.params[1];
        let mut all_with_local_generations = all.clone();
        all_with_local_generations.extend([
            BorrowRoot::Local(pair_local),
            BorrowRoot::Local(replacement_local),
        ]);
        let pair_fact = checker.normalize_borrow_fact(
            pair_ty,
            BorrowFact::from_direct([BorrowRoot::Param(0)].into_iter().collect()),
        );
        checker.borrows.assign(pair_local, pair_fact.clone());
        checker.borrows.assign(
            replacement_local,
            BorrowFact::from_direct([BorrowRoot::Param(1)].into_iter().collect()),
        );
        let replacement = Expr {
            kind: ExprKind::Local(replacement_local),
            ty: Ty::Str,
            span: function.span,
        };
        let left = Expr {
            kind: ExprKind::Field {
                root: pair_local,
                path: vec![0],
            },
            ty: Ty::Str,
            span: function.span,
        };
        for malformed in [
            Expr {
                kind: ExprKind::StructLit {
                    struct_id: u32::MAX,
                    fields: vec![left.clone(), replacement.clone()],
                },
                ty: pair_ty,
                span: function.span,
            },
            Expr {
                kind: ExprKind::Tuple {
                    tuple_id: u32::MAX,
                    elems: vec![left, replacement.clone()],
                },
                ty: tuple_ty,
                span: function.span,
            },
        ] {
            assert_eq!(
                checker
                    .project_fact_or_flatten(
                        malformed.ty,
                        checker.borrow_fact(&malformed),
                        &[match malformed.kind {
                            ExprKind::StructLit { .. } => BorrowProjection::StructField(0),
                            _ => BorrowProjection::TupleElement(0),
                        }],
                        Ty::Str,
                    )
                    .flatten(),
                all_with_local_generations,
                "a malformed product constructor must flatten every child parameter and local-generation root"
            );
        }

        for (path, value) in [
            (
                vec![
                    BorrowProjection::StructField(0),
                    BorrowProjection::StructField(0),
                ],
                replacement.clone(),
            ),
            (
                vec![BorrowProjection::StructField(0)],
                Expr {
                    ty: pair_ty,
                    ..replacement
                },
            ),
        ] {
            checker.borrows.assign(pair_local, pair_fact.clone());
            checker.replace_local_borrow_projection(pair_local, &path, &value);
            assert_eq!(
                checker
                    .local_projected_fact(
                        pair_local,
                        &[BorrowProjection::StructField(0)],
                        Ty::Str,
                    )
                    .flatten(),
                all_with_local_generations,
                "a malformed product write must retain old and incoming parameter and local-generation roots"
            );
        }
    }

    #[test]
    fn malformed_borrow_mut_retention_indices_fail_closed() {
        let mut valid_roots = BorrowRoots::new();
        valid_roots.insert(BorrowRoot::Param(1));
        let valid = vec![valid_roots];
        assert_eq!(
            exact_borrow_mut_source_indices(Some(&valid), 0, 2),
            Some(vec![BorrowMutRetentionSource::Contained(1)])
        );

        let mut storage_roots = BorrowRoots::new();
        storage_roots.insert(BorrowRoot::ParamStorage(1));
        let storage = vec![storage_roots];
        assert_eq!(
            exact_borrow_mut_source_indices(Some(&storage), 0, 2),
            Some(vec![BorrowMutRetentionSource::Storage(1)]),
        );

        let mut out_of_range_roots = BorrowRoots::new();
        out_of_range_roots.insert(BorrowRoot::Param(2));
        let out_of_range = vec![out_of_range_roots];
        assert_eq!(
            exact_borrow_mut_source_indices(Some(&out_of_range), 0, 2),
            None,
            "an out-of-range source must select the conservative caller fallback",
        );

        let mut non_parameter_roots = BorrowRoots::new();
        non_parameter_roots.insert(BorrowRoot::Local(0));
        let non_parameter = vec![non_parameter_roots];
        assert_eq!(
            exact_borrow_mut_source_indices(Some(&non_parameter), 0, 2),
            None,
            "a non-parameter root must not become a fail-open empty exact set",
        );
        assert_eq!(exact_borrow_mut_source_indices(Some(&valid), 1, 2), None);
        assert_eq!(exact_borrow_mut_source_indices(None, 0, 2), None);

        assert_eq!(
            borrow_mut_source_indices(Some(&valid), 0, 2),
            vec![BorrowMutRetentionSource::Contained(1)],
            "a valid exact summary must not be widened",
        );
        let conservative = vec![
            BorrowMutRetentionSource::Contained(0),
            BorrowMutRetentionSource::Storage(0),
            BorrowMutRetentionSource::Contained(1),
            BorrowMutRetentionSource::Storage(1),
        ];
        assert_eq!(borrow_mut_source_indices(None, 0, 2), conservative);
        assert_eq!(
            borrow_mut_source_indices(Some(&out_of_range), 0, 2),
            conservative,
            "a malformed exact summary must supply both conservative edge kinds",
        );
    }

    #[test]
    fn indirect_borrow_mut_exempts_only_argument_and_rejects_callee_capture() {
        let (program, diagnostics) = check(
            "\
fn replace(borrow mut value: string) {}
fn probe() {
  mut value := \"before\".clone()
  apply := replace
  apply(value)
}
fn main() -> i32 = 0
",
        );
        assert!(!diagnostics.has_errors());
        let function = program
            .fns
            .iter()
            .find(|function| function.name == "probe")
            .expect("probe function");
        let call = function
            .body
            .value
            .as_deref()
            .filter(|expression| matches!(expression.kind, ExprKind::CallFnValue { .. }))
            .or_else(|| {
                function.body.stmts.iter().find_map(|statement| match statement {
                    hir::Stmt::Expr(
                        expression @ Expr {
                            kind: ExprKind::CallFnValue { .. },
                            ..
                        },
                    ) => Some(expression),
                    _ => None,
                })
            })
            .expect("indirect call");
        let ExprKind::CallFnValue { callee, args } = &call.kind else {
            unreachable!("selected an indirect call")
        };
        let ExprKind::Local(callee_local) = &callee.kind else {
            panic!("function value must be a local")
        };
        let ExprKind::Local(argument_local) = &args[0].kind else {
            panic!("exclusive argument must be a local")
        };
        let named = program
            .fns
            .iter()
            .map(|function| (function.name.clone(), function.return_borrow.clone()))
            .collect();
        let named_modes = program
            .fns
            .iter()
            .map(|function| (function.name.clone(), function.param_modes.clone()))
            .collect();
        let named_borrow_mut_retention = std::collections::HashMap::new();
        let callable_targets = vec![CallableTargetSet::new(); program.fn_types.len()];
        let callable_target_ids = std::collections::HashMap::new();
        let parallel_targets = CallableTransferSet::new();
        let mut sink = Diagnostics::new();
        let mut checker = MoveCheck {
            f: function,
            diags: &mut sink,
            named_return_borrow: &named,
            named_parallel_transfer: &named,
            named_param_modes: &named_modes,
            named_borrow_mut_retention: &named_borrow_mut_retention,
            summary_dependencies: None,
            tuples: &program.tuples,
            structs: &program.structs,
            enums: &program.enums,
            tagged_types: &program.tagged_types,
            fn_types: &program.fn_types,
            callable_targets: &callable_targets,
            callable_target_ids: &callable_target_ids,
            callable_parallel_targets: &parallel_targets,
            loop_breaks: Vec::new(),
            #[cfg(test)]
            loop_borrow_breaks: Vec::new(),
            #[cfg(test)]
            loop_value_breaks: Vec::new(),
            borrows: BorrowState::default(),
            next_pipeline_snapshot: 0,
            loop_value_facts: std::collections::HashMap::new(),
            control_value_facts: std::collections::HashMap::new(),
            walked_value_facts: std::collections::HashMap::new(),
            walked_storage_facts: std::collections::HashMap::new(),
            walked_backing_facts: std::collections::HashMap::new(),
            pending_call_completions: std::collections::HashMap::new(),
            mutable_call_argument_snapshots: std::collections::HashSet::new(),
            borrow_mut_place_snapshots: std::collections::HashSet::new(),
            value_snapshot_frames: Vec::new(),
            reported_invalid_value_actions: std::collections::HashSet::new(),
            loop_iter_drops: Vec::new(),
            arena_depth: 0,
            return_roots: BorrowRoots::new(),
            parallel_transfer_roots: BorrowRoots::new(),
            borrow_mut_retention: vec![BorrowRoots::new(); function.params.len()],
            non_fallthrough: std::collections::HashSet::new(),
            borrow_fact_cache: std::cell::RefCell::new(None),
            collecting_move_children: false,
            move_children: Vec::new(),
            borrowed_projection_locals: borrowed_projection_locals(&function.body),
        };
        assert!(
            checker.intentional_action_snapshot(call, MoveCheck::expr_key(&args[0])),
            "the exact exclusive-argument snapshot is the one intentional generation transition",
        );
        assert!(
            !checker.intentional_action_snapshot(call, MoveCheck::expr_key(callee)),
            "a single borrow-mut argument must not suppress the callee snapshot",
        );

        checker.borrows.assign(
            *callee_local,
            BorrowFact::from_direct([BorrowRoot::Local(*argument_local)].into_iter().collect()),
        );
        let Ty::Fn(function_type) = callee.ty else {
            panic!("callee must have a function-value type")
        };
        let modes = checker.fn_types[function_type as usize]
            .params
            .iter()
            .map(|(mode, _)| *mode)
            .collect::<Vec<_>>();
        checker.check_indirect_call_callee_aliases(callee, args, &modes);
        drop(checker);
        assert!(
            sink.iter().any(|diagnostic| diagnostic
                .message
                .contains("function value captures an owner invalidated by exclusive argument 1")),
            "a callee environment retaining the exclusive argument's owner must be rejected",
        );
    }

    #[test]
    fn native_output_buffers_require_mut_locals_at_all_five_sites() {
        let cases = [
            (
                ".read()",
                "import std.fs\nfn main() -> Result<(), Error> {\n  r := fs.open(\"input\")?\n",
                "r.read(ARG)?",
            ),
            (
                ".read_line()",
                "import std.fs\nfn main() -> Result<(), Error> {\n  r := fs.open(\"input\")?\n  br := r.buffered()\n",
                "br.read_line(ARG)?",
            ),
            (
                ".pread()",
                "import std.fs\nfn main() -> Result<(), Error> {\n  f := fs.open_rw(\"input\")?\n",
                "f.pread(ARG, 0)?",
            ),
            (
                ".recv_from()",
                "import std.net\nfn main() -> Result<(), Error> {\n  u := udp.bind(\"127.0.0.1\", 1)?\n",
                "u.recv_from(ARG)?",
            ),
            (
                "crypto.random",
                "import std.crypto\nfn main() -> Result<(), Error> {\n",
                "crypto.random(ARG)\n",
            ),
        ];
        for (operation, prefix, call) in cases {
            let source = format!(
                "{prefix}  mut b := buffer(4)\n  {}\n  return Ok(())\n}}\n",
                call.replace("ARG", "\"not a buffer\"")
            );
            let (_, diagnostics) = check(&source);
            assert!(
                diagnostics.has_errors(),
                "{operation} with a wrong buffer type must fail"
            );
            assert!(
                !diagnostics.iter().any(|diagnostic| {
                    diagnostic.message.contains("needs a mut buffer local")
                        || diagnostic.message.contains("cannot fill immutable buffer")
                }),
                "{operation} must preserve the earlier wrong-type diagnostic: {:?}",
                diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
            );

            for (label, arg, expected) in [
                (
                    "non-local",
                    "buffer(4)",
                    format!("'{operation}' needs a mut buffer local (bind it first, then pass that local)"),
                ),
                (
                    "immutable",
                    "b",
                    format!("cannot fill immutable buffer 'b' in '{operation}' (declare with mut)"),
                ),
            ] {
                let source = format!(
                    "{prefix}  b := buffer(4)\n  {}\n  return Ok(())\n}}\n",
                    call.replace("ARG", arg)
                );
                let (_, diagnostics) = check(&source);
                assert!(
                    diagnostics.iter().any(|diagnostic| diagnostic.message == expected),
                    "{operation} {label} must report {expected:?}; got {:?}",
                    diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
                );
            }

            let source = format!(
                "{prefix}  mut b := buffer(4)\n  {}\n  return Ok(())\n}}\n",
                call.replace("ARG", "b")
            );
            let (_, diagnostics) = check(&source);
            assert!(
                !diagnostics.has_errors(),
                "{operation} with a mut local must check: {:?}",
                diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
            );
        }

        let (_, diagnostics) = check(
            "import std.fs\nfn main() -> Result<(), Error> {\n  f := fs.open_rw(\"input\")?\n  b := buffer(4)\n  f.pread(b, \"bad offset\")?\n  return Ok(())\n}\n",
        );
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic.message.contains("'.pread()' offset must be i64")),
            "pread must retain the later offset diagnostic before the mutability gate: {:?}",
            diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
        );
        assert!(
            !diagnostics.iter().any(|diagnostic| diagnostic.message.contains("cannot fill immutable buffer")),
            "pread must not mask the invalid offset with the mutability diagnostic: {:?}",
            diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
        );
    }

    #[test]
    fn lifted_function_origin_metadata_is_explicit() {
        let (program, diagnostics) = check(
            "\
fn identity<T>(value: T) -> T = value
fn named(value: i64) -> i64 = value
pub fn exported(value: i64) -> i64 = value
fn main() -> i32 {
  captured := 2
  plain := [1, 2].map(fn value { value + 1 }).sum()
  closed := [1, 2].map(fn value { value + captured }).sum()
  return identity(named(plain + closed)) as i32
}
",
        );
        assert!(!diagnostics.has_errors());
        assert_eq!(
            program
                .fns
                .iter()
                .find(|function| function.name == "named")
                .expect("ordinary named function")
                .origin,
            hir::FnOrigin::Source {
                is_entry: true,
                is_public: false,
            }
        );
        assert_eq!(
            program
                .fns
                .iter()
                .find(|function| function.name == "exported")
                .expect("public source function")
                .origin,
            hir::FnOrigin::Source {
                is_entry: true,
                is_public: true,
            }
        );
        assert!(!
            program
                .fns
                .iter()
                .find(|function| function.name == "exported")
                .expect("public source function")
                .origin
                .is_exportable()
        );
        let main = program
            .fns
            .iter()
            .find(|function| function.name == "main")
            .expect("entry source function");
        assert_eq!(
            main.origin,
            hir::FnOrigin::Source {
                is_entry: true,
                is_public: false,
            }
        );
        assert!(!main.origin.is_exportable());
        assert_eq!(
            program
                .fns
                .iter()
                .find(|function| function.name.starts_with("identity$"))
                .expect("generic monomorph")
                .origin,
            hir::FnOrigin::Monomorph
        );
        assert!(!hir::FnOrigin::Monomorph.is_exportable());
        let mut lifted = program
            .fns
            .iter()
            .filter_map(|function| match function.origin {
                hir::FnOrigin::Lifted { capture_count } => Some(capture_count),
                _ => None,
            })
            .collect::<Vec<_>>();
        lifted.sort_unstable();
        assert_eq!(
            lifted,
            vec![0, 1],
            "non-capturing and one-capture lambdas keep distinct explicit metadata"
        );
        assert!(
            program.fns.iter().filter(|function| matches!(
                function.origin,
                hir::FnOrigin::Lifted { .. }
            )).all(|function| !function.origin.is_exportable())
        );
    }

    #[test]
    fn imported_effect_and_absent_transfer_facts_are_normalized() {
        let mut diagnostics = Diagnostics::new();
        let lib_source = "module lib\npub fn read(borrow value: i64) -> i64 = value\n";
        let main_source = "module main\nimport lib\nfn main() -> i32 = 0\n";
        let lib_tokens = tokenize(1, lib_source, &mut diagnostics);
        let lib = parse_file(lib_tokens, &mut diagnostics);
        let main_tokens = tokenize(0, main_source, &mut diagnostics);
        let main = parse_file(main_tokens, &mut diagnostics);
        assert!(
            !diagnostics.has_errors(),
            "fixture parse failed: {:?}",
            diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
        );
        let modules = [
            Module {
                path: "lib".to_string(),
                file: &lib,
                is_entry: false,
                interface_only: true,
            },
            Module {
                path: "main".to_string(),
                file: &main,
                is_entry: true,
                interface_only: false,
            },
        ];

        for (provided, expected) in [
            (Some(FnEffect::Pure), FnEffect::Pure),
            (Some(FnEffect::Impure), FnEffect::Impure),
            (Some(FnEffect::Unknown), FnEffect::Unknown),
            (None, FnEffect::Impure),
        ] {
            let mut external_effects = HashMap::new();
            if let Some(effect) = provided {
                external_effects.insert("lib$read".to_string(), effect);
            }
            let mut diagnostics = Diagnostics::new();
            let program = check_program_with_interface_facts(
                &modules,
                &external_effects,
                &HashMap::new(),
                &mut diagnostics,
            );
            assert!(
                !diagnostics.has_errors(),
                "imported effect fixture failed for {provided:?}: {:?}",
                diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
            );
            let imported = program
                .imported_fns
                .iter()
                .find(|function| function.name == "lib$read")
                .expect("imported declaration");
            assert_eq!(imported.effect, expected, "provided effect: {provided:?}");
            assert_eq!(
                imported.parallel_transfer_params,
                [0],
                "an absent transfer fact must conservatively select borrowed scalar storage",
            );
        }
    }

    #[test]
    fn non_entry_public_function_origin_is_exportable() {
        let mut diagnostics = Diagnostics::new();
        let lib_source = "module lib\npub fn exported(value: i64) -> i64 = value\n";
        let main_source = "module main\nimport lib\nfn main() -> i32 = 0\n";
        let lib_tokens = tokenize(1, lib_source, &mut diagnostics);
        let lib = parse_file(lib_tokens, &mut diagnostics);
        let main_tokens = tokenize(0, main_source, &mut diagnostics);
        let main = parse_file(main_tokens, &mut diagnostics);
        let modules = [
            Module {
                path: "lib".to_string(),
                file: &lib,
                is_entry: false,
                interface_only: false,
            },
            Module {
                path: "main".to_string(),
                file: &main,
                is_entry: true,
                interface_only: false,
            },
        ];
        let program = check_program(&modules, &mut diagnostics);
        assert!(
            !diagnostics.has_errors(),
            "fixture failed: {:?}",
            diagnostics.iter().map(|diagnostic| &diagnostic.message).collect::<Vec<_>>()
        );
        let function = program
            .fns
            .iter()
            .find(|function| function.name == "lib$exported")
            .expect("non-entry public source function");
        assert_eq!(
            function.origin,
            hir::FnOrigin::Source {
                is_entry: false,
                is_public: true,
            }
        );
        assert!(function.origin.is_exportable());
    }

    #[test]
    fn pipeline_terminal_diagnostic_order() {
        let (_, diagnostics) = check(
            "\
fn main() -> i32 {
  missing.map().reduce(also_missing, fn acc, x { acc + x })
  return 0
}
",
        );
        let messages = diagnostics
            .iter()
            .map(|diagnostic| diagnostic.message.as_str())
            .collect::<Vec<_>>();
        assert!(
            messages
                .iter()
                .any(|message| message.contains("undefined name: 'missing'")),
            "the receiver/source diagnostic must be retained: {messages:?}"
        );
        assert!(
            messages
                .iter()
                .all(|message| !message.contains("needs a function")
                    && !message.contains("also_missing")),
            "the earliest invalid source suppresses later malformed-stage and terminal-init diagnostics: {messages:?}"
        );
    }

    #[test]
    fn pipeline_terminal_snapshot_action_order_matrix() {
        let (program, diagnostics) = check(
            "\
fn stopped() -> i64 {
  return [1].map(fn x {
    print(x)
    x
  }).reduce({
    return 7
    0
  }, fn acc, x { acc + x })
}
fn live() -> i64 {
  return [1].map(fn x {
    print(x)
    x
  }).reduce(0, fn acc, x { acc + x })
}
fn main() -> i32 = 0
",
        );
        assert!(
            !diagnostics.has_errors(),
            "fixture must check: {:?}",
            diagnostics
                .iter()
                .map(|diagnostic| &diagnostic.message)
                .collect::<Vec<_>>()
        );
        let effects = fn_effects(&program, &std::collections::HashMap::new());
        assert_eq!(
            effects.get("stopped"),
            Some(&FnEffect::Pure),
            "a terminating init must prevent the earlier stage callback action"
        );
        assert_eq!(
            effects.get("live"),
            Some(&FnEffect::Impure),
            "the all-fallthrough twin must join the stage callback action"
        );
    }

