    fn json_encode_struct_array_checks() {
        let (_p, d) = check("import core.json\nUser { id: i64, name: str }\nfn main() -> i32 {\n  us := [User{id: 1, name: \"a\"}, User{id: 2, name: \"b\"}]\n  print(json.encode(us))\n  return 0\n}\n");
        assert!(!d.has_errors(), "json.encode of a struct array should check");
    }

    #[test]
    fn json_encode_rejects_non_struct() {
        let (_p, d) = check("import core.json\nfn main() -> i32 {\n  x := 5\n  print(json.encode(x))\n  return 0\n}\n");
        assert!(d.has_errors(), "json.encode requires a struct");
    }

    #[test]
    fn json_encode_rejects_unsupported_field() {
        // A char field is a valid struct field but not encodable yet; json.encode must error
        // (and not return a malformed template).
        let (_p, d) = check("import core.json\nC { ch: char, n: i32 }\nfn main() -> i32 {\n  c := C{ch: 'x', n: 1}\n  print(json.encode(c))\n  return 0\n}\n");
        assert!(d.has_errors(), "json.encode rejects a struct with an unsupported field type");
    }

    #[test]
    fn print_rejects_non_scalar() {
        // An Option is not a printable scalar.
        let (_p, d) = check("fn main() -> i32 {\n  print(Some(1))\n  return 0\n}\n");
        assert!(d.has_errors(), "print rejects non-scalar values like Option");
    }

    #[test]
    fn reduce_checks() {
        let (_p, d) = check(
            "fn add(acc: i32, x: i32) -> i32 = acc + x\nfn main() -> i32 {\n  return [1, 2, 3].reduce(0, add)\n}\n",
        );
        assert!(!d.has_errors(), "reduce with a matching fold should check");
    }

    #[test]
    fn any_all_check_and_require_scalar_element() {
        let (_p, ok) = check("fn big(x: i64) -> bool = x > 4\nfn pos(x: i64) -> bool = x > 0\nfn main() -> i32 {\n  if [1, 2, 3].any(big) { return 1 }\n  if [1, 2, 3].all(pos) { return 2 }\n  return 0\n}\n");
        assert!(!ok.has_errors(), "any/all over a scalar array should check");
        // A struct element (no projection) is rejected — project a field first.
        let (_q, bad) = check("fn f(e: i32) -> bool = e > 0\nE { pay: i32 }\nfn main() -> i32 {\n  if [E{pay: 1}].any(f) { return 1 }\n  return 0\n}\n");
        assert!(bad.has_errors(), "any on a struct element must error");
        // An undefined predicate errors (and returns Ty::Error, not a valid bool node).
        let (_r, undef) = check("fn main() -> i32 {\n  if [1, 2, 3].any(nope) { return 1 }\n  return 0\n}\n");
        assert!(undef.has_errors(), "any with an undefined predicate must error");
    }

    #[test]
    fn count_checks_on_scalar_and_struct_arrays() {
        // count returns i64 and needs no scalar element (a struct element is fine).
        let (_p, d) = check("fn big(x: i64) -> bool = x > 2\nE { active: bool }\nfn main() -> i32 {\n  a := [1, 2, 3].where(big).count()\n  b := [E{active: true}, E{active: false}].where(.active).count()\n  if a + b == 3 { return 1 }\n  return 0\n}\n");
        assert!(!d.has_errors(), "count should check on scalar and struct array pipelines");
    }

    #[test]
    fn field_projection_from_slice_source_rejected() {
        // A `slice<Struct>` parameter is constructible, but a `.field` projection needs a
        // slot-backed source (MIR `IndexField`); projecting from a `{ptr,len}` view would
        // miscompile, so reject it cleanly.
        let (_p, d) = check("P { pay: i32, active: bool }\nfn total(xs: slice<P>) -> i32 = xs.pay.sum()\nfn main() -> i32 { return 0 }\n");
        assert!(d.has_errors(), "field projection from a slice source must be rejected");
    }

    #[test]
    fn to_array_inside_arena_checks() {
        // MMv2 slice 3: `.to_array()` inside an arena yields an owned array (consumed here).
        let (_p, d) = check("fn double(x: i32) -> i32 = x * 2\nfn main() -> i32 {\n  arena {\n    return [1, 2, 3].map(double).to_array().sum()\n  }\n}\n");
        assert!(!d.has_errors(), "to_array inside an arena should check");
    }

    #[test]
    fn to_array_outside_arena_now_allowed() {
        // MMv2 slice 4: `.to_array()` outside an arena is free-standing (heap + drop), so it
        // checks (the owned array is dropped at function exit).
        let (_p, d) = check("fn double(x: i32) -> i32 = x * 2\nfn main() -> i32 {\n  return [1, 2, 3].map(double).to_array().sum()\n}\n");
        assert!(!d.has_errors(), "to_array outside an arena is now free-standing (heap + drop)");
    }

    #[test]
    fn to_array_owned_cannot_escape_arena() {
        // The owned array is arena-allocated (region Arena(k)); letting it escape as the arena
        // block's value (bound outside the arena) must be rejected.
        let (_p, d) = check("fn double(x: i32) -> i32 = x * 2\nfn main() -> i32 {\n  bad := arena {\n    [1, 2, 3].map(double).to_array()\n  }\n  return 0\n}\n");
        assert!(d.has_errors(), "an arena-allocated owned array must not escape its arena");
    }

    #[test]
    fn str_bytes_view_preserves_headerless_source_region() {
        let static_view =
            "fn view() -> Result<str, Error> = \"hello\".bytes().as_str()\nfn main() -> i32 = 0\n";
        let (_program, diagnostics) = check(static_view);
        assert!(
            !diagnostics.has_errors(),
            "a byte view of a static str literal must remain returnable",
        );

        let local_view = "fn bad() -> Result<str, Error> {\n  owned := \"hello\".clone()\n  return owned.bytes().as_str()\n}\nfn main() -> i32 = 0\n";
        let (_program, diagnostics) = check(local_view);
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic
                .message
                .contains("cannot return a view that borrows local storage")),
            "the same view over a frame-owned string must remain non-returnable",
        );
    }

    #[test]
    fn arena_owned_move_arguments_are_rejected() {
        let direct =
            "fn take(xs: array<i64>) -> i64 = xs.sum()\nfn main() -> i32 {\n  arena {\n    xs := [1, 2, 3].to_array()\n    return take(xs) as i32\n  }\n}\n";
        let (_p, d) = check(direct);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "a direct call must not transfer arena-owned storage to a callee"
        );

        let indirect =
            "fn take(xs: array<i64>) -> i64 = xs.sum()\nfn main() -> i32 {\n  f := take\n  arena {\n    xs := [1, 2, 3].to_array()\n    return f(xs) as i32\n  }\n}\n";
        let (_p, d) = check(indirect);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "an indirect call must not transfer arena-owned storage to a callee"
        );

        let aggregate =
            "fn make() -> array<i64> = [1].to_array()\nfn take(t: (array<i64>, array<i64>)) -> i64 = t.0.sum() + t.1.sum()\nfn main() -> i32 {\n  arena {\n    heap := make()\n    local := [2].to_array()\n    return take((heap, local)) as i32\n  }\n}\n";
        let (_p, d) = check(aggregate);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "an aggregate containing arena-owned storage must not cross the call boundary"
        );

        let joined =
            "fn make() -> array<i64> = [1].to_array()\nfn take(xs: array<i64>) -> i64 = xs.sum()\nfn run(c: bool) -> i32 {\n  arena {\n    mut xs := make()\n    if c {\n      xs = [2].to_array()\n    }\n    return take(xs) as i32\n  }\n}\nfn main() -> i32 = run(false)\n";
        let (_p, d) = check(joined);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "a path-joined local that may be arena-owned must not transfer to a callee"
        );
    }

    #[test]
    fn free_standing_owned_move_arguments_are_allowed() {
        let array =
            "fn take(xs: array<i64>) -> i64 = xs.sum()\nfn main() -> i32 {\n  xs := [1, 2, 3].to_array()\n  return take(xs) as i32\n}\n";
        let (_p, d) = check(array);
        assert!(!d.has_errors(), "a free-standing owned array may transfer to a callee");

        let heap_string =
            "fn take(s: string) -> i64 = s.len()\nfn main() -> i32 {\n  arena {\n    s := \"hello\".clone()\n    return take(s) as i32\n  }\n}\n";
        let (_p, d) = check(heap_string);
        assert!(
            !d.has_errors(),
            "a heap-owned string remains free-standing even when created inside an arena"
        );

        let borrowed_result =
            "fn copy(xs: slice<i64>) -> array<i64> = xs.to_array()\nfn take(xs: array<i64>) -> i64 = xs.sum()\nfn main() -> i32 {\n  arena {\n    local := [1, 2, 3].to_array()\n    heap := copy(local)\n    return take(heap) as i32\n  }\n}\n";
        let (_p, d) = check(borrowed_result);
        assert!(
            !d.has_errors(),
            "a free-standing call result remains transferable when its borrow region is arena-shortened"
        );
    }

    #[test]
    fn explicit_region_call_results_cannot_cross_a_by_value_call() {
        let prefix = "Row { values: array<str> }\nE { Bad }\nfn next(out: region) -> Result<Option<Row>, E> {\n  mut values: array_builder<str> := array_builder(out)\n  values.push(\"seven\".clone_in(out))\n  return Ok(Some(Row { values: values.build() }))\n}\n";
        let by_value = format!(
            "{prefix}fn take(row: Row) -> i64 = row.values[0].len()\nfn main() -> i32 {{\n  arena out {{\n    selected := next(out) else {{ return 1 }}\n    row := selected else {{ return 2 }}\n    return take(row) as i32\n  }}\n}}\n"
        );
        let (program, diagnostics) = check(&by_value);
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic
                .message
                .contains("cannot be moved into a function call")),
            "a tagged success projected from an explicit-region call must retain arena ownership: next={:?}, diagnostics={:?}",
            program.fns.iter().find(|function| function.name == "next").map(|function| &function.return_region),
            diagnostics.iter().map(|diagnostic| diagnostic.message.as_str()).collect::<Vec<_>>(),
        );

        let matched = format!(
            "{prefix}fn take(row: Row) -> i64 = row.values[0].len()\nfn main() -> i32 {{\n  arena out {{\n    row := match next(out) {{\n      Err(_) => {{ return 1 }}\n      Ok(selected) => match selected {{\n        None => {{ return 2 }}\n        Some(value) => value\n      }}\n    }}\n    return take(row) as i32\n  }}\n}}\n"
        );
        let (_program, diagnostics) = check(&matched);
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic
                .message
                .contains("cannot be moved into a function call")),
            "match projection must retain the selected explicit-region ownership bit"
        );

        let propagated = format!(
            "{prefix}fn take(row: Row) -> i64 = row.values[0].len()\nfn use(out: region) -> Result<i64, E> {{\n  selected := next(out)?\n  row := selected else {{ return Ok(0) }}\n  return Ok(take(row))\n}}\nfn main() -> i32 {{\n  arena out {{\n    value := use(out) else {{ return 1 }}\n    return value as i32\n  }}\n}}\n"
        );
        let (_program, diagnostics) = check(&propagated);
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic
                .message
                .contains("cannot be moved into a function call")),
            "`?` projection must retain the selected explicit-region ownership bit"
        );

        let borrowed = format!(
            "{prefix}fn inspect(borrow row: Row) -> i64 = row.values[0].len()\nfn main() -> i32 {{\n  arena out {{\n    selected := next(out) else {{ return 1 }}\n    row := selected else {{ return 2 }}\n    return inspect(row) as i32\n  }}\n}}\n"
        );
        let (_program, diagnostics) = check(&borrowed);
        assert!(
            !diagnostics.has_errors(),
            "a shared borrow must inspect the same explicit-region result without transferring ownership"
        );

        let free_standing = "Row { values: array<str> }\nE { Bad }\nfn next() -> Result<Option<Row>, E> = Ok(Some(Row { values: [\"seven\"].to_array() }))\nfn take(row: Row) -> i64 = row.values[0].len()\nfn main() -> i32 {\n  selected := next() else { return 1 }\n  row := selected else { return 2 }\n  return take(row) as i32\n}\n";
        let (_program, diagnostics) = check(free_standing);
        assert!(
            !diagnostics.has_errors(),
            "a free-standing Move call result must retain legal by-value transfer"
        );
    }

    #[test]
    fn nested_clone_in_value_retains_only_the_destination_region() {
        let source = "ByteView { bytes: slice<u8> }\nValue { Bytes(ByteView) }\nfn copy(view: slice<u8>, out: region) -> array<Value> {\n  mut values: array_builder<Value> := array_builder(out)\n  values.push(Value.Bytes(ByteView { bytes: view.clone_in(out) }))\n  return values.build()\n}\nfn main() -> i32 = 0\n";
        let (_, diagnostics) = check(source);
        assert!(
            !diagnostics.has_errors(),
            "clone_in recursively severs a nested view's source provenance: {:?}",
            diagnostics.iter().collect::<Vec<_>>()
        );
    }

    #[test]
    fn map_err_obeys_move_call_transfer_rules() {
        let arena_owned =
            "fn discard(xs: array<i64>) -> i64 = xs.len()\nfn main() -> i32 {\n  arena {\n    r: Result<(), array<i64>> := Err([1, 2].to_array())\n    mapped := r.map_err(discard)\n    return 0\n  }\n}\n";
        let (_p, d) = check(arena_owned);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "map_err must not transfer an arena-owned Move error to its mapper"
        );

        let free_standing =
            "fn make() -> array<i64> = [1, 2].to_array()\nfn discard(xs: array<i64>) -> i64 = xs.len()\nfn main() -> i32 {\n  r: Result<(), array<i64>> := Err(make())\n  mapped := r.map_err(discard)\n  return 0\n}\n";
        let (_p, d) = check(free_standing);
        assert!(!d.has_errors(), "map_err may transfer a free-standing Move error");

        let captured_str =
            "E { Bad }\nfn leak() -> Result<i64, str> {\n  owned := \"x\".clone()\n  view: str := owned\n  r: Result<i64, E> := Err(E.Bad)\n  return r.map_err(fn _: E { view })\n}\n";
        let (_p, d) = check(captured_str);
        assert!(
            d.iter().any(|e| e.message.contains("cannot return a view that borrows local storage")),
            "map_err must not return a mapper result borrowed from a frame-local closure capture"
        );
    }

    #[test]
    fn pipeline_functions_reject_move_values_by_value() {
        let map =
            "P { xs: array<i64> }\nfn take(p: P) -> i64 = p.xs.len()\nfn main() -> i32 {\n  rows := [P { xs: [1, 2].to_array() }]\n  return rows.map(take).sum() as i32\n}\n";
        let (_p, d) = check(map);
        assert!(
            d.iter().any(|e| e.message.contains("'map' cannot pass a Move element by value")),
            "map must not copy a Move element into a callee"
        );

        let where_ =
            "P { xs: array<i64> }\nfn keep(p: P) -> bool = p.xs.len() > 0\nfn main() -> i32 {\n  rows := [P { xs: [1, 2].to_array() }]\n  return rows.where(keep).count() as i32\n}\n";
        let (_p, d) = check(where_);
        assert!(
            d.iter().any(|e| e.message.contains("'where' cannot pass a Move element by value")),
            "where must not copy a Move element into a callee"
        );

        let reduce =
            "P { xs: array<i64> }\nfn add(acc: i64, p: P) -> i64 = acc + p.xs.len()\nfn main() -> i32 {\n  rows := [P { xs: [1, 2].to_array() }]\n  return rows.reduce(0, add) as i32\n}\n";
        let (_p, d) = check(reduce);
        assert!(
            d.iter().any(|e| e.message.contains("'reduce' cannot pass a Move element by value")),
            "reduce must not copy a Move element into a callee"
        );

        let fixed_array_accumulator =
            "P { xs: array<i64> }\nfn main() -> i32 {\n  rows := [P { xs: [1].to_array() }]\n  folded := [1, 2].reduce(rows, fn acc, x { acc })\n  return folded.len() as i32\n}\n";
        let (_p, d) = check(fixed_array_accumulator);
        assert!(
            d.iter().any(|e| e.message.contains("'reduce' cannot pass a Move accumulator by value")),
            "reduce must reject an inferred fixed Move-struct array accumulator"
        );

        let map_result =
            "fn make(x: i64) -> array<i64> = [x].to_array()\nfn main() -> i32 {\n  return [1, 2].map(make).count() as i32\n}\n";
        let (_p, d) = check(map_result);
        assert!(
            d.iter().any(|e| e.message.contains("'map' cannot produce a Move element")),
            "map must not leak a Move result on every pipeline iteration"
        );
    }

    /// The copy-position side of the same rule: a value an operation *buffers*, *collects*,
    /// *views*, *rearranges*, *draws*, or *writes* must be Copy too, because the checked-HIR body
    /// validator refuses a Move value in each of those positions (`ty_copy_ok` / `scalar_copy_ok`).
    ///
    /// The axis is the **reachable `slice<Move>` parameter domain**: `slice<string>` is a
    /// declarable and passable parameter type even though no expression can build such a value, so
    /// "a Move element collection cannot be constructed" never proves a gate unreachable. Three of
    /// these six rows (`shuffle`, `sample`, `map_into`) were live internal errors that argument had
    /// dismissed.
    ///
    /// This owner pins the exact diagnostics. `align_mir`'s
    /// `move_copy_positions_are_refused_by_the_producer_not_the_boundary` owns the stronger
    /// property — that the *build* stops here and never reaches the MIR boundary.
    #[test]
    fn move_copy_positions_are_rejected() {
        // The type that makes the whole axis reachable: unbuildable as a value, legal as a type.
        let param = "fn take(xs: slice<string>) -> i64 = xs.len()\nfn main() -> i32 = 0\n";
        let (_p, d) = check(param);
        assert!(!d.has_errors(), "a `slice<string>` parameter must stay declarable and passable");

        for (name, source, expected) in [
            // `Ord` admits owned `string`, but the fused sort buffers one key per element with no
            // per-key drop — orderability alone is not enough.
            (
                "sort_by_key key",
                "fn key(x: i64) -> string = \"k\".clone()\nfn main() -> i32 {\n  s := [3, 1, 2].sort_by_key(key)\n  return s[0] as i32\n}\n",
                "'sort_by_key' cannot buffer a Move key",
            ),
            // `to_array`'s Move-*struct* arm had a message; its scalar arm admitted any
            // `ty_to_scalar`, owned `string` included.
            (
                "to_array element",
                "fn f(xs: slice<string>) -> i64 = xs.to_array().len()\nfn main() -> i32 = 0\n",
                "'to_array' cannot collect a Move element",
            ),
            // `chunks` asked only `scalar_to_prim`, which admits `String`.
            (
                "chunks element",
                "fn f(xs: slice<string>) -> i64 = xs.chunks(2).len()\nfn main() -> i32 = 0\n",
                "'chunks' cannot view a Move element",
            ),
            // Fisher-Yates swaps raw `{ptr,len}` headers through the slice.
            (
                "shuffle element",
                "import std.rand\nfn scramble(out xs: slice<string>) {\n  mut r := rand.seed_with(1)\n  r.shuffle(xs)\n}\nfn main() -> i32 = 0\n",
                "'shuffle' cannot rearrange a Move element",
            ),
            // `sample` copies the drawn values into a fresh owned `array<T>` — a double free.
            (
                "sample element",
                "import std.rand\nfn pick(xs: slice<string>) -> i64 {\n  mut r := rand.seed_with(1)\n  s := r.sample(xs, 1)\n  return s.len()\n}\nfn main() -> i32 = 0\n",
                "'sample' cannot draw a Move element",
            ),
            // `map_into` overwrites the destination's owned headers without dropping them.
            (
                "map_into element",
                "fn fill(src: slice<string>, out dst: slice<string>) {\n  src.map_into(dst)\n}\nfn main() -> i32 = 0\n",
                "'map_into' cannot write a Move element",
            ),
        ] {
            let (_p, d) = check(source);
            assert!(
                d.iter().any(|e| e.message.contains(expected)),
                "{name}: expected {expected:?}, got {:?}",
                d.iter().map(|e| e.message.clone()).collect::<Vec<_>>()
            );
        }

        // Over-rejecting would take the whole surface away: a borrowed `str` key is orderable and
        // Copy, and every Copy element still passes each gate.
        for (name, source) in [
            ("str key", "fn key(x: i64) -> str = \"k\"\nfn main() -> i32 {\n  s := [3, 1, 2].sort_by_key(key)\n  return s[0] as i32\n}\n"),
            ("copy to_array", "fn f(xs: slice<i64>) -> i64 = xs.to_array().len()\nfn main() -> i32 = 0\n"),
            ("copy chunks", "fn f(xs: slice<i64>) -> i64 = xs.chunks(2).len()\nfn main() -> i32 = 0\n"),
            ("copy shuffle", "import std.rand\nfn scramble(out xs: slice<i64>) {\n  mut r := rand.seed_with(1)\n  r.shuffle(xs)\n}\nfn main() -> i32 = 0\n"),
            ("copy sample", "import std.rand\nfn pick(xs: slice<i64>) -> i64 {\n  mut r := rand.seed_with(1)\n  s := r.sample(xs, 1)\n  return s.len()\n}\nfn main() -> i32 = 0\n"),
            ("copy map_into", "fn fill(src: slice<i64>, out dst: slice<i64>) {\n  src.map_into(dst)\n}\nfn main() -> i32 = 0\n"),
        ] {
            let (_p, d) = check(source);
            assert!(
                !d.has_errors(),
                "{name}: a Copy value must still be accepted, got {:?}",
                d.iter().map(|e| e.message.clone()).collect::<Vec<_>>()
            );
        }
    }

    #[test]
    fn fixed_move_struct_array_cannot_be_captured_by_value() {
        let src =
            "P { xs: array<i64> }\nfn main() -> i32 {\n  rows := [P { xs: [1].to_array() }]\n  f := fn { rows.len() }\n  return f() as i32\n}\n";
        let (_p, d) = check(src);
        assert!(
            d.iter().any(|e| e.message.contains("cannot capture the owned value 'rows'")),
            "a fixed Move-struct array capture would copy and double-drop its elements"
        );
    }

    #[test]
    fn task_group_is_not_a_general_allocation_arena() {
        let heap_new =
            "fn main() -> i32 {\n  task_group {\n    p := heap.new(7)\n    print(p.get())\n  }\n  return 0\n}\n";
        let (_p, d) = check(heap_new);
        assert!(
            d.iter().any(|e| e.message.contains("heap.new must be used inside an `arena {}`")),
            "task_group storage is reserved for spawned environments/results"
        );

        let free_standing =
            "fn main() -> i32 {\n  task_group {\n    xs := [1, 2].to_array()\n    print(xs.len())\n  }\n  return 0\n}\n";
        let (p, d) = check(free_standing);
        assert!(!d.has_errors(), "ordinary owned values remain valid inside a task_group");
        let main = p.fns.iter().find(|f| f.name == "main").expect("main HIR");
        let xs = main.locals.iter().find(|l| l.name == "xs").expect("xs local");
        assert!(
            main.drop_individual_locals.contains(&xs.id),
            "to_array without an explicit arena must keep its individual cleanup inside task_group"
        );

        let explicit =
            "fn main() -> i32 {\n  task_group {\n    arena {\n      p := heap.new(7)\n      print(p.get())\n    }\n  }\n  return 0\n}\n";
        let (_p, d) = check(explicit);
        assert!(!d.has_errors(), "an explicit arena inside task_group still provides general region allocation");
    }

    #[test]
    fn reduce_and_scan_results_preserve_borrowed_pipeline_regions() {
        let reduce =
            "fn pick(acc: str, x: str) -> str = x\nfn leak() -> str {\n  return task_group {\n    owned := \"x\".clone()\n    view: str := owned\n    views := [view]\n    views.reduce(\"\", pick)\n  }\n}\nfn main() -> i32 = 0\n";
        let (_p, d) = check(reduce);
        assert!(
            d.iter()
                .any(|e| e.message.contains("cannot escape as the block's value")),
            "reduce must not let a source-borrowing result escape its task_group"
        );

        let scan =
            "fn pick(acc: str, x: str) -> str = x\nfn leak() -> array<str> {\n  return task_group {\n    owned := \"x\".clone()\n    view: str := owned\n    views := [view]\n    views.scan(\"\", pick)\n  }\n}\nfn main() -> i32 = 0\n";
        let (_p, d) = check(scan);
        assert!(
            d.iter()
                .any(|e| e.message.contains("cannot escape as the block's value")),
            "scan must not let source-borrowing elements escape their task_group"
        );
    }

    #[test]
    fn owned_aggregates_require_one_allocation_mode() {
        let tuple =
            "fn make() -> array<i64> = [1].to_array()\nfn main() -> i32 {\n  arena {\n    heap := make()\n    local := [2].to_array()\n    t := (heap, local)\n    print(t.0.len())\n  }\n  return 0\n}\n";
        let (_p, d) = check(tuple);
        assert!(
            d.iter().any(|e| e.message.contains("cannot mix free-standing and arena-owned")),
            "a tuple with mixed owned allocation modes must be rejected"
        );

        let strukt =
            "Pair { left: array<i64>, right: array<i64> }\nfn make() -> array<i64> = [1].to_array()\nfn main() -> i32 {\n  arena {\n    heap := make()\n    local := [2].to_array()\n    p := Pair { left: heap, right: local }\n    print(p.left.len())\n  }\n  return 0\n}\n";
        let (_p, d) = check(strukt);
        assert!(
            d.iter().any(|e| e.message.contains("cannot mix free-standing and arena-owned")),
            "a struct with mixed owned allocation modes must be rejected"
        );

        let uniform =
            "fn make() -> array<i64> = [1].to_array()\nfn main() -> i32 {\n  heap := (make(), make())\n  print(heap.0.len())\n  arena {\n    local := ([1].to_array(), [2].to_array())\n    print(local.1.len())\n  }\n  return 0\n}\n";
        let (_p, d) = check(uniform);
        assert!(!d.has_errors(), "uniform heap and uniform arena aggregates must remain legal");

        let arena_struct_call =
            "Pair { left: array<i64>, right: array<i64> }\nfn take(p: Pair) -> i64 = p.left.len() + p.right.len()\nfn main() -> i32 {\n  arena {\n    p := Pair { left: [1].to_array(), right: [2].to_array() }\n    return take(p) as i32\n  }\n}\n";
        let (_p, d) = check(arena_struct_call);
        assert!(
            d.iter().any(|e| e.message.contains("cannot be moved into a function call")),
            "a bound uniformly arena-owned struct must retain arena provenance"
        );

        let field_reassign =
            "Pair { left: array<i64>, right: array<i64> }\nfn make() -> array<i64> = [1].to_array()\nfn main() -> i32 {\n  arena {\n    mut p := Pair { left: make(), right: make() }\n    p.right = [2].to_array()\n    print(p.left.len())\n  }\n  return 0\n}\n";
        let (_p, d) = check(field_reassign);
        assert!(
            d.iter()
                .any(|e| e.message.contains("field replacement of array<i64> is not supported yet")),
            "owned-array field replacement must fail closed before it can introduce mixed aggregate ownership"
        );

        let joined_field =
            "Wrap { xs: array<i64> }\nfn make() -> array<i64> = [1].to_array()\nfn run(c: bool) -> i32 {\n  arena {\n    mut w := Wrap { xs: make() }\n    if c {\n      w = Wrap { xs: [2].to_array() }\n    }\n    w.xs = [3].to_array()\n    return 0\n  }\n}\nfn main() -> i32 = run(false)\n";
        let (_p, d) = check(joined_field);
        assert!(
            d.iter()
                .any(|e| e.message.contains("field replacement of array<i64> is not supported yet")),
            "a heap/arena path-dependent aggregate must reject unsupported owned-field mutation"
        );
    }

    #[test]
    fn move_owned_local_through_if_arm_rejected() {
        // MMv2 slice 4.5: moving a *bound* owned array out through an `if`/`else` arm is a
        // deferred-feature error (codegen only nulls slots at direct move sites). A fresh
        // temporary through an `if` is fine — there is no bound slot to double-free.
        let (_p, d) = check("fn double(x: i32) -> i32 = x * 2\nfn pick(c: bool) -> array<i32> {\n  ys := [1, 2, 3].map(double).to_array()\n  zs := [4, 5, 6].map(double).to_array()\n  return if c { ys } else { zs }\n}\nfn main() -> i32 = 0\n");
        assert!(d.has_errors(), "moving a bound owned local out through an if/else arm must error");
    }

    #[test]
    fn conditional_move_then_no_later_use_checks() {
        // Moving an owned local on only one path (with no later use of the source) is allowed:
        // MIR nulls the slot at the move site so the not-moved path is still freed at exit.
        let (_p, d) = check("fn double(x: i32) -> i32 = x * 2\nfn run(c: bool) -> i32 {\n  ys := [1, 2, 3].map(double).to_array()\n  mut total := 0\n  if c {\n    zs := ys\n    total = zs.sum()\n  }\n  return total\n}\nfn main() -> i32 = run(true)\n");
        assert!(!d.has_errors(), "a one-path move with no later use of the source should check");
    }

    #[test]
    fn min_over_non_numeric_errors() {
        // `min`/`max` need a numeric element, like `sum`. A bool-producing map is rejected.
        let (_p, d) = check("fn isbig(x: i32) -> bool = x > 1\nfn main() -> i32 {\n  if [1, 2, 3].map(isbig).min() { return 1 }\n  return 0\n}\n");
        assert!(d.has_errors(), "min over a non-numeric element must error");
    }

    #[test]
    fn min_max_inline_checks() {
        let (_p, d) = check("fn id(x: i32) -> i32 = x\nfn main() -> i32 {\n  return [3, 1, 2].map(id).min() + [3, 1, 2].map(id).max()\n}\n");
        assert!(!d.has_errors(), "min + max over an i32 pipeline should check");
    }

    #[test]
    fn scan_inline_checks() {
        // scan(init, f) with f: (i32, i32) -> i32 yields array<i32>; summing it checks.
        let (_p, d) = check("fn add(acc: i32, x: i32) -> i32 = acc + x\nfn id(x: i32) -> i32 = x\nfn main() -> i32 {\n  return [1, 2, 3].map(id).scan(0, add).sum()\n}\n");
        assert!(!d.has_errors(), "scan(0, add) over an i32 pipeline should check");
    }

    #[test]
    fn scan_fn_arity_mismatch_errors() {
        // scan needs a 2-arg fold; a 1-arg function must error.
        let (_p, d) = check("fn bad(x: i32) -> i32 = x\nfn main() -> i32 {\n  return [1, 2, 3].scan(0, bad).sum()\n}\n");
        assert!(d.has_errors(), "scan with a non-binary function must error");
    }

    #[test]
    fn sort_inline_checks() {
        let (_p, d) = check("fn id(x: i32) -> i32 = x\nfn h(acc: i32, x: i32) -> i32 = acc + x\nfn main() -> i32 {\n  return [3, 1, 2].map(id).sort().reduce(0, h)\n}\n");
        assert!(!d.has_errors(), "sort of a numeric pipeline should check");
    }

    #[test]
    fn sort_over_struct_element_rejected() {
        let (_p, d) = check("Point { x: i32, y: i32 }\nfn main() -> i32 {\n  s := [Point { x: 1, y: 2 }].sort()\n  return 0\n}\n");
        assert!(d.has_errors(), "sort over struct elements must error (project a field first)");
    }

    #[test]
    fn dot_length_mismatch_errors() {
        let (_p, d) = check("fn main() -> i32 {\n  xs := [1, 2, 3]\n  ys := [4, 5]\n  return xs.dot(ys)\n}\n");
        assert!(d.has_errors(), "dot of unequal-length arrays must error");
    }

    #[test]
    fn dot_element_type_mismatch_errors() {
        // An int array dotted with a float array must error (no implicit numeric coercion).
        let (_p, d) = check("fn main() -> i32 {\n  xs := [1, 2, 3]\n  ys := [1.0, 2.0, 3.0]\n  if xs.dot(ys) == 0 { return 1 }\n  return 0\n}\n");
        assert!(d.has_errors(), "dot of mismatched element types must error");
    }

    #[test]
    fn dot_arbitrary_right_operand_rejected_not_panicked() {
        // An `if` expression as the right operand is an arbitrary array expr; it must be
        // rejected in sema, not reach `array_source_slot` and panic in MIR.
        let (_p, d) = check("fn main() -> i32 {\n  xs := [1, 2, 3]\n  ys := [4, 5, 6]\n  zs := [7, 8, 9]\n  c := true\n  if xs.dot(if c { ys } else { zs }) == 32 { return 1 }\n  return 0\n}\n");
        assert!(d.has_errors(), "an arbitrary array expr as dot's right operand must error");
    }

    #[test]
    fn dot_inline_checks() {
        let (_p, d) = check("fn main() -> i32 {\n  xs := [2, 3, 4]\n  ys := [5, 6, 7]\n  if xs.dot(ys) == 56 { return 1 }\n  return 0\n}\n");
        assert!(!d.has_errors(), "dot of two equal-length i64 arrays should check");
    }

    #[test]
    fn scan_over_struct_element_rejected_not_panicked() {
        // A struct element (no field projection) must be rejected in sema, not panic in MIR.
        let (_p, d) = check("Point { x: i32, y: i32 }\nfn addx(acc: i32, p: Point) -> i32 = acc + p.x\nfn main() -> i32 {\n  return [Point { x: 1, y: 2 }].scan(0, addx).sum()\n}\n");
        assert!(d.has_errors(), "scan over struct elements must error (project a field first)");
    }

    #[test]
    fn scan_struct_accumulator_rejected() {
        // A struct accumulator (ty_to_scalar succeeds for structs) must be rejected explicitly.
        let (_p, d) = check("Acc { s: i32 }\nfn step(a: Acc, x: i32) -> Acc = Acc { s: a.s + x }\nfn id(x: i32) -> i32 = x\nfn main() -> i32 {\n  return [1, 2, 3].map(id).scan(Acc { s: 0 }, step).len()\n}\n");
        assert!(d.has_errors(), "scan with a struct accumulator must error");
    }

